python3 txn_report.py --selftest && python3 -c "
import random
random.seed(1)
with open('big.csv','w') as f:
    f.write('txn_id,customer_id,amount\n')
    for i in range(2_000_000):
        r = random.random()
        if r < 0.001: f.write(f'{i},c{i%5000}\n')
        elif r < 0.002: f.write(f'{i},c{i%5000},oops\n')
        elif r < 0.0021: f.write(f'{i},c1,\"' + 'x'*200000 + '\"\n')
        else: f.write(f'{i},c{i%5000},{random.randint(-500,99999)/100}\n')
" && time python3 txn_report.py big.csv && head -4 report.csv && head -4 rejects.csv | cut -c1-80 && wc -l report.csv rejects.csv && rm big.csv report.csv rejects.csv
